from scipy.integrate import quad


def potential_at(P, Q, x, y):
    a = quad(lambda s: P(s, 0), 0, x)[0]
    b = quad(lambda s: Q(x, s), 0, y)[0]
    return a + b


def passes_local_test(P, Q, points, h=1e-5, tol=1e-6):
    for (x, y) in points:
        p_y = (P(x, y + h) - P(x, y - h)) / (2 * h)
        q_x = (Q(x + h, y) - Q(x - h, y)) / (2 * h)
        if abs(p_y - q_x) >= tol:
            return False
    return True

from scipy.integrate import quad


def work_polyline(F, vertices):
    total = 0.0
    for A, B in zip(vertices, vertices[1:]):
        d = [b - a for a, b in zip(A, B)]

        def g(t):
            p = tuple(a + t * di for a, di in zip(A, d))
            return sum(f * di for f, di in zip(F(p), d))
        total += quad(g, 0, 1)[0]
    return total
